<script setup lang="ts">
import { useApi } from '~/composables/useApi';

import type { Listing, PriceHistory } from '~/types/api'
import { money, dateTR, listingStatus, listingFacts, listingName } from '~/utils/format'
const route=useRoute();const api=useApi();const id=String(route.params.id);const row=ref<Listing|null>(null);const history=ref<PriceHistory[]>([]);const state=ref<'loading'|'error'|'success'>('loading');const error=ref('')
async function load(){state.value='loading';error.value='';try{const [l,h]=await Promise.all([api.listing(id),api.priceHistory(id)]);row.value=l;history.value=h;state.value='success'}catch(e){state.value='error';error.value=e instanceof Error?e.message:'İlan detayı alınamadı.'}}
await load()
</script>
<template><div class="page-heading"><div><p class="eyebrow">PORTFÖY / İLAN DETAYI</p><h1>{{ row?.title || (row ? listingName(row) : `İlan #${id}`) }}</h1><p>İlanın ayırt edici bilgileri, kayıt ayrıntıları ve sistemde gözlenen fiyat geçmişi.</p></div><div class="heading-actions"><NuxtLink :to="`/listings/${id}/edit`" class="button button-secondary">✎ Düzenle</NuxtLink><NuxtLink to="/listings" class="button button-primary">← İlanlar</NuxtLink></div></div><StatePanel v-if="state==='loading'" state="loading"/><StatePanel v-else-if="state==='error'" state="error" :message="error" @retry="load"/><template v-else-if="row"><div class="detail-grid"><section class="panel"><div class="panel-header"><div><h2>İlan bilgileri</h2><p>{{ row.transaction_type === 'rent' ? 'Kiralık ilan · aylık bedel' : 'Satılık ilan' }} · Gayrimenkul #{{ row.property_id }}</p></div><span class="status-badge" :class="`status-${row.status}`">{{ listingStatus(row.status) }}</span></div><p class="eyebrow">İSTENEN İLAN FİYATI</p><div class="detail-price">{{ money(row.asking_price,row.currency) }}</div><p class="panel-footnote">Bu değer ilanda istenen fiyattır; gerçekleşmiş satış fiyatı olarak yorumlanmamalıdır.</p><div v-if="row.location_label" class="table-sub listing-location mt-16">📍 {{ row.location_label }}</div><div v-if="listingFacts(row).length" class="listing-facts"><span v-for="fact in listingFacts(row)" :key="fact" class="chip">{{ fact }}</span></div><div class="detail-meta mt-16"><div><span>İlan numarası</span><b>#{{ row.id }}</b></div><div><span>Gayrimenkul ID</span><b>#{{ row.property_id }}</b></div><div><span>Kaydı oluşturan kullanıcı</span><b>#{{ row.created_by }}</b></div><div><span>Kayıt türü</span><b>{{ row.source_type==='manual'?'Manuel':row.source_type==='import'?'İçe aktarılan':'Yetkili kaynak' }}</b></div><div><span>Kaynak adı</span><b>{{ row.source_name||'—' }}</b></div><div><span>Harici ilan ID</span><b>{{ row.source_listing_id||'—' }}</b></div><div><span>İlan başlığı</span><b>{{ row.title||'Başlık girilmemiş' }}</b></div><div><span>İşlem türü</span><b>{{ row.transaction_type === 'rent' ? 'Kiralık (aylık)' : 'Satılık' }}</b></div><div><span>Yayın tarihi</span><b>{{ dateTR(row.published_at) }}</b></div><div><span>Son görüldüğü tarih</span><b>{{ dateTR(row.last_seen_at) }}</b></div><div><span>Oluşturulma</span><b>{{ dateTR(row.created_at) }}</b></div><div><span>Son güncelleme</span><b>{{ dateTR(row.updated_at) }}</b></div><div v-if="row.archived_at"><span>Arşivlenme</span><b>{{ dateTR(row.archived_at) }}</b></div></div><div v-if="row.source_url" class="mt-16"><a :href="row.source_url" target="_blank" rel="noopener noreferrer" class="text-link">Kaynak ilanı aç ↗</a></div><div v-if="row.notes" class="mt-16"><p class="eyebrow">NOTLAR</p><p>{{ row.notes }}</p></div></section><section class="panel"><div class="panel-header"><div><h2>Fiyat geçmişi</h2><p>Sisteme kaydedilen fiyat gözlemleri</p></div><span class="chip">{{ history.length }} kayıt</span></div><StatePanel v-if="!history.length" state="empty" message="Bu ilan için fiyat geçmişi kaydı bulunamadı."/><div v-else class="chart-bars"><div v-for="item in history" :key="item.id" class="saved-filter"><div><h3>{{ money(item.asking_price,item.currency) }}</h3><p>{{ dateTR(item.recorded_at) }} · {{ item.change_reason }}</p></div><span class="chip">#{{ item.id }}</span></div></div><p class="panel-footnote">İlk kayıt gerçek ilk yayın fiyatı olmayabilir. Geçmiş, yalnızca uygulamada gözlenen fiyat değişimlerini gösterir.</p><NuxtLink :to="`/listings/${id}/price-history`" class="button button-secondary mt-16">Geçmişi ayrıntılı gör →</NuxtLink></section></div></template></template>
